\section*{Claim}
For the $SU(3)$ one-matrix subsector, the double-trace loop equation closes after substituting the finite-$N$ triple-trace reduction: every generated term is expressible using only single- and double-trace variables
\[
\operatorname{Tr}U^a,
\qquad
\operatorname{Tr}U^a\operatorname{Tr}U^b.
\]
\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad U\in SU(3),\qquad \operatorname{Tr}A=\frac13\operatorname{tr}A.\\
\text{(P2)}&\quad \text{The double-trace loop equation contains generated terms of the form }\operatorname{Tr}U^i\operatorname{Tr}U^j\operatorname{Tr}U^k.\\
\text{(P3)}&\quad \operatorname{Tr}U^i\operatorname{Tr}U^j\operatorname{Tr}U^k
=-\frac{2}{9}\operatorname{Tr}U^{i+j+k}+\frac13\operatorname{Tr}U^i\operatorname{Tr}U^{j+k}+\frac13\operatorname{Tr}U^{i+j}\operatorname{Tr}U^k\\
&\quad\quad\quad\quad\quad +\frac13\operatorname{Tr}U^{i+k}\operatorname{Tr}U^j+\frac13\operatorname{Tr}U^{j-i}\operatorname{Tr}U^{k-i}-\frac19\operatorname{Tr}U^{j+k-2i}.\\
\text{(P4)}&\quad \mathcal V_{SU(3)}:=\operatorname{span}\{\operatorname{Tr}U^a,\operatorname{Tr}U^a\operatorname{Tr}U^b:a,b\in\mathbb Z\}.\\
\text{(P5)}&\quad \text{The remaining non-triple terms in the same loop equation are already in }\mathcal V_{SU(3)}.
\end{aligned}
\]
\section*{Derivation}
Consider any generated triple-trace monomial
\begin{align}
Y_{i,j,k}&:=\operatorname{Tr}U^i\operatorname{Tr}U^j\operatorname{Tr}U^k.
\end{align}
By (P3), $Y_{i,j,k}$ is equal to a finite linear combination of the six terms
\begin{align}
&\operatorname{Tr}U^{i+j+k},\quad
\operatorname{Tr}U^i\operatorname{Tr}U^{j+k},\quad
\operatorname{Tr}U^{i+j}\operatorname{Tr}U^k,\\
&\operatorname{Tr}U^{i+k}\operatorname{Tr}U^j,
\quad \operatorname{Tr}U^{j-i}\operatorname{Tr}U^{k-i},
\quad \operatorname{Tr}U^{j+k-2i}.
\end{align}
Each listed term is either a single normalized trace or a product of two normalized traces. Hence each listed term belongs to $\mathcal V_{SU(3)}$ by (P4). Therefore
\begin{align}
Y_{i,j,k}\in\mathcal V_{SU(3)}.
\end{align}
By (P2), these are precisely the potentially non-retained generated terms, and by (P5) all other terms are already retained. Substituting (P3) into the loop equation therefore produces an equation entirely in $\mathcal V_{SU(3)}$.
\section*{Final Result}
\[
\boxed{SU(3)\text{ one-matrix loop equations close on single- and double-trace variables after triple-trace reduction}.}
\]
\hfill$\blacksquare$

