\section*{Claim}
The plaquette bootstrap is a semidefinite program whose validity is logically prior to interval tightness. More constraints can only improve the interval after projection, provided the stronger hierarchy projects into the weaker feasible set.
\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad \mathcal F_{\Lambda}:=\{w:A_{\Lambda}w=b_{\Lambda},\ M_{r,\Lambda}(w)\succeq0\text{ for all retained }r\}.\\
\text{(P2)}&\quad A_{\Lambda}w=b_{\Lambda}\text{ is affine and each }M_{r,\Lambda}(w)\text{ is affine in }w.\\
\text{(P3)}&\quad u_P(w)=c_P^Tw\text{ is linear}.\\
\text{(P4)}&\quad \Pi_{\Lambda+1\to\Lambda}\mathcal F_{\Lambda+1}\subseteq\mathcal F_{\Lambda}\text{ for the common retained coordinates}.\\
\text{(P5)}&\quad L_{\Lambda}:=\min_{w\in\mathcal F_{\Lambda}}u_P(w),\qquad U_{\Lambda}:=\max_{w\in\mathcal F_{\Lambda}}u_P(w).\\
\text{(P6)}&\quad \text{Validity means the exact projected vector is feasible; tightness means }U_{\Lambda}-L_{\Lambda}\text{ is small}.
\end{aligned}
\]
\section*{Derivation}
First, $\mathcal F_{\Lambda}$ is convex. If $w^{(1)},w^{(2)}\in\mathcal F_{\Lambda}$ and $t\in[0,1]$, then
\begin{align}
A_{\Lambda}(tw^{(1)}+(1-t)w^{(2)})
&=tA_{\Lambda}w^{(1)}+(1-t)A_{\Lambda}w^{(2)}\\
&=b_{\Lambda},
\end{align}
and affine positive-semidefinite blocks obey
\begin{align}
M_{r,\Lambda}(tw^{(1)}+(1-t)w^{(2)})
&=tM_{r,\Lambda}(w^{(1)})+(1-t)M_{r,\Lambda}(w^{(2)})\succeq0.
\end{align}
Thus optimizing the linear objective (P3) over $\mathcal F_{\Lambda}$ is an SDP.

Second, assume the projection nesting (P4). For any $z\in\mathcal F_{\Lambda+1}$, its projected common-coordinate vector lies in $\mathcal F_{\Lambda}$. Therefore the feasible set for the stronger projected problem is a subset of the weaker one, so
\begin{align}
L_{\Lambda}&\le L_{\Lambda+1},\\
U_{\Lambda+1}&\le U_{\Lambda}.
\end{align}
Hence the width cannot increase after adding valid constraints:
\begin{align}
U_{\Lambda+1}-L_{\Lambda+1}\le U_{\Lambda}-L_{\Lambda}.
\end{align}
This tightening statement is conditional on (P4), while certification itself depends on exact feasibility as in (P6).
\section*{Final Result}
\[
\boxed{\text{Valid SDP constraints give certified intervals; nested valid strengthenings can only tighten them.}}
\]
\hfill$\blacksquare$

