\section*{Claim}
The Creutz-ratio output from retained rectangular Wilson loops is a finite-rectangle estimator. For $T,L\ge2$ and
\[
R_{T,L}:=\frac{W(T,L)W(T-1,L-1)}{W(T-1,L)W(T,L-1)}>0,
\]
the quantity
\[
a^2\sigma_{T,L,\lambda}:=-\log R_{T,L}
\]
is exactly computable from the four retained rectangle variables, but it is a certified infinite-area string tension only under an additional residual-control assumption.
\section*{Premises}
\[
\begin{aligned}
\text{(P1)}&\quad W(T,L),\ W(T-1,L-1),\ W(T-1,L),\ W(T,L-1)\text{ are retained or computable in one feasible-set solution}.\\
\text{(P2)}&\quad R_{T,L}>0.\\
\text{(P3)}&\quad W(T,L)=\exp\{-a^2\sigma TL+r(T,L)\}.\\
\text{(P4)}&\quad \chi(T,L):=-\log R_{T,L}.\\
\text{(P5)}&\quad \Delta r:=r(T,L)+r(T-1,L-1)-r(T-1,L)-r(T,L-1).\\
\text{(P6)}&\quad \text{The implemented small-loop extraction uses }T=3,L=2.
\end{aligned}
\]
\section*{Derivation}
By (P2), the logarithm is well-defined. Taking logarithms using (P3),
\begin{align}
\log R_{T,L}
&=\log W(T,L)+\log W(T-1,L-1)-\log W(T-1,L)-\log W(T,L-1)\\
&=(-a^2\sigma TL+r(T,L))+(-a^2\sigma (T-1)(L-1)+r(T-1,L-1))\\
&\quad-(-a^2\sigma (T-1)L+r(T-1,L))-(-a^2\sigma T(L-1)+r(T,L-1))\\
&=-a^2\sigma+\Delta r,
\end{align}
because
\begin{align}
-TL-(T-1)(L-1)+(T-1)L+T(L-1)=-1.
\end{align}
Therefore
\begin{align}
\chi(T,L)&=a^2\sigma-\Delta r.
\end{align}
For the implemented small rectangle,
\begin{align}
a^2\sigma_{3,2,\lambda}
&=-\log\frac{W(3,2)W(2,1)}{W(2,2)W(3,1)}.
\end{align}
Thus the computation is internally well-defined from retained Wilson loops, while interpreting it as the physical string tension requires controlling or neglecting $\Delta r$.
\section*{Final Result}
\[
\boxed{a^2\sigma_{T,L,\lambda}=\chi(T,L)=a^2\sigma-\Delta r,\quad\text{so finite rectangles give qualitative estimates unless }\Delta r\text{ is controlled}.}
\]
\hfill$\blacksquare$

